// Music: Gourmet Race (64), Nintendo / HAL Laboratory, arranged by Hirokazu Ando.
// The source recording's repeated passage is 64.25240625 seconds long.
// https://www.101soundboards.com/sounds/26333311-12-gourmet-race-64
// English SSBU countdown and game calls, from the Announcer Voice soundboard:
// https://www.101soundboards.com/boards/1618184-super-smash-bros-ultimate-nintendo-switch-announcer-voice
(() => {
  const loopStart = 4;
  const loopEnd = 68.25240625;

  // PLAY_SE on the sword and the victim's CUTUP_L collision are separate.
  // The latter's playback rates were measured in the selected #18086 bout.
  const swordCuts=new Map([[21,1.0373],[35,1.0870],[48,1.0844],[59,1.1466],
    [71,1.1635],[83,1.1467],[97,1.1421],[109,1.1296],[173,1.032]]);

  // Frames follow the sound ACMDs, not the overlapping attack hitbox windows:
  // github.com/WuBoytH/SSBU-Dumped-Scripts/tree/main/smashline/{purin,kirby}
  // The Kirby hammer release begins after frame 15 of the charging animation.
  const cues = {
    puffUp_start:[[1,'se_purin_final01']],
    puffUp_attack:[[10,'vc_purin_007']],
    puffUp_end:[[1,'se_purin_final02']],
    ultraSword_start:[[4,'se_kirby_final01'],[20,'se_kirby_final02'],[50,'se_kirby_final03'],[50,'vc_kirby_010']],
    ultraSword_attack:[[1,'se_kirby_final04'],[7,'se_kirby_final05_l',110],
      // ACMD calls final07 for the seven follow-ups. The public wave archive
      // has no separate 07 recording, so its swing still uses the 06 sample.
      ...[21,35,48,59,71,83,97,109].map(n=>[n,'se_kirby_final06']),
      [116,'vc_kirby_final01'],[134,'se_kirby_final08'],[174,'se_kirby_final09'],[174,'vc_kirby_final02']],
    kirbyGreeting: [[6,'vc_kirby_appeal01']],
    kirbyJab1: [[2,'se_kirby_swing_s']], kirbyJab2: [[3,'se_kirby_swing_s']],
    puffJab1: [[5,'se_purin_swing_s']], puffJab2: [[5,'se_purin_swing_m']],
    rapidJab: [[1,'vc_kirby_attack02'],[5,'se_kirby_attack100',Infinity]],
    rapidEnd: [[1,'se_kirby_swing_m']],
    // PurinSpecialNHoldMax/init plays Hash40 0x1613202bd9 on entry.
    copiedRollout: [[51,'vc_kirby_copy_purin_01']],
    sing: [[27,'vc_purin_003'],[65,'vc_purin_004']],
    rest: [[34,'vc_purin_001'],[34,'se_purin_sleep'],[134,'se_purin_sleep']],
    inhale: [[2,'se_kirby_special_n01'],[10,'se_kirby_special_n07',44]],
    hammer: [[17,'vc_kirby_002']],
    cutter: [[3,'vc_kirby_006'],[3,'se_kirby_special_h01'],[23,'se_kirby_special_h02']],
    cutterLand: [[2,'vc_kirby_008']],
  };

  function create() {
    let context, master, musicGain, voiceGain, moveGain, musicBuffer, musicNode, voiceNode;
    let enabled = true, active = false, paused = false;
    let offset = 0, beganAt = 0, announcement = 0;
    const calls = new Map(), samples = new Map();
    const tracks = Array.from({length:2}, () => ({action:'',frame:0,notes:new Set()}));
    const impacts = new Set();

    function clearNotes(notes) {
      for (const node of notes) { node.stop(); node.disconnect(); }
      notes.clear();
    }

    function clearMoves() {
      for (const track of tracks) {
        clearNotes(track.notes); track.action=''; track.frame=0;track.launch=false;track.charging=false;
      }
      clearNotes(impacts);
    }

    function sample(name, notes, age=0, loop=false, rate=1, level=1) {
      const buffer=samples.get(name);
      if (!buffer || (!loop && age >= buffer.duration)) return;
      const node=context.createBufferSource();
      node.buffer=buffer; node.loop=loop;
      node.playbackRate.value=rate;
      const gain=level===1?null:context.createGain();
      if(gain){gain.gain.value=level;gain.connect(moveGain);}
      node.connect(gain||moveGain); notes.add(node);
      node.onended=()=>{ notes.delete(node); node.disconnect();gain?.disconnect(); };
      node.start(0,loop ? age % buffer.duration : age);
      return node;
    }

    function updateMoves(fighters, events) {
      if (!context || !enabled || paused || !active) return;
      const played=new Set();
      for (const f of fighters) {
        const track=tracks[f.index], copiedRollout=f.kind==='kirby' && f.action==='rollout';
        // The charge animation holds on frame 15, while the full-charge cue
        // follows elapsed move time through the hold and subsequent roll.
        const final=f.action==='puffUp' || f.action==='ultraSword';
        const frame=final?f.finalFrame:f.actionFrame+(copiedRollout ? f.chargeHold : 0);
        if(final && track.phase!==f.finalPhase){track.phase=f.finalPhase;track.frame=0;}
        if (track.action!==f.action || frame<track.frame) {
          clearNotes(track.notes);
          if(f.action==='shield') sample('guard',impacts);
          if(f.action==='shieldDrop') sample('guardOff',impacts);
          if(f.action==='ledge') sample('ledge',impacts);
          if(f.action!=='stun') track.launch=false;
          track.action=f.action; track.frame=0;
        }
        if(track.launch && !f.hitlag && f.action==='stun'){sample('launch',impacts);track.launch=false}
        if(f.charge>0 && !track.charging && /smash$/.test(f.action))sample('smashCharge',impacts);
        track.charging=f.charge>0;
        let sequence=cues[final?f.action+'_'+f.finalPhase:f.action];
        if(f.action==='jab' || f.action==='jab2') {
          const first=f.action==='jab';
          sequence=f.kind==='kirby'?(first?cues.kirbyJab1:cues.kirbyJab2):(first?cues.puffJab1:cues.puffJab2);
        }
        if(copiedRollout && f.charge===36) sequence=cues.copiedRollout;
        if(f.kind==='kirby' && f.action==='taunt' && f.tauntVariant==='down') sequence=cues.kirbyGreeting;
        if (sequence && frame!==track.frame) {
          for (const [onset,name,loopUntil] of sequence) {
            if (track.frame < onset && frame >= onset && (!loopUntil || frame <= loopUntil)) {
              // Restoring a paused/muted match may enter a cue halfway through.
              // Relative to the confirmed final08/final09 levels, final04
              // is 0.46 as loud in the same match's audio.
              const node=sample(name,track.notes,(frame-onset)/60,!!loopUntil,1,name==='se_kirby_final04'?.46:1);
              if (node && loopUntil) track.loop=node;
            }
            if (loopUntil && track.frame <= loopUntil && frame > loopUntil && track.loop) {
              if (track.notes.has(track.loop)) track.loop.stop();
              track.loop=null;
            }
          }
        }
        track.frame=frame;
      }
      for (const e of events) {
        let name=e.type;
        if(e.type==='hit') {
          name=e.move==='rest'?'rest_ping':e.sfx;
          if(e.move==='ultraSword'){
            const caster=fighters[e.fighter],n=caster.finalFrame;
            const rate=caster.finalPhase==='attack'?swordCuts.get(n):
              caster.finalPhase==='start' && n>=54 && n<61?1.036:0;
            if(rate && sample('cutup_l',impacts,0,false,rate,.60))played.add(e);
          }
          if(!name && e.move?.startsWith('throw')) name='throw';
          if(e.strong) tracks[e.target].launch=true;
        } else if(e.type==='land') name=fighters[e.fighter].platform===0?'grass':'wood';
        else if(!['parry','shieldHit','shieldBreak'].includes(e.type)) continue;
        if(name && sample(name,impacts)) played.add(e);
      }
      return played;
    }

    function decode(encoded) {
      const bytes = Uint8Array.from(atob(encoded), c => c.charCodeAt(0));
      return context.decodeAudioData(bytes.buffer);
    }

    function silenceVoice() {
      announcement++;
      if (voiceNode) {
        voiceNode.stop();
        voiceNode.disconnect();
        voiceNode = null;
      }
    }

    function stopMusic(remember) {
      if (!musicNode) return;
      if (remember) {
        offset += context.currentTime - beganAt;
        if (offset >= loopEnd) offset = loopStart + (offset-loopStart) % (loopEnd-loopStart);
      }
      musicNode.stop();
      musicNode.disconnect();
      musicNode = null;
    }

    function playMusic() {
      if (!musicBuffer || musicNode || !active || paused) return;
      musicNode = context.createBufferSource();
      musicNode.buffer = musicBuffer;
      musicNode.loop = true;
      musicNode.loopStart = loopStart;
      musicNode.loopEnd = Math.min(loopEnd, musicBuffer.duration);
      musicNode.connect(musicGain);
      beganAt = context.currentTime;
      musicNode.start(0, offset);
    }

    function unlock() {
      if (!context) {
        const Audio = globalThis.AudioContext || globalThis.webkitAudioContext;
        if (!Audio) return;
        context = new Audio();
        master = context.createGain();
        master.gain.value = enabled ? 1 : 0;
        master.connect(context.destination);
        musicGain = context.createGain();
        musicGain.gain.value = .12;
        musicGain.connect(master);
        voiceGain = context.createGain();
        voiceGain.gain.value = .55;
        voiceGain.connect(master);
        moveGain = context.createGain();
        moveGain.gain.value = .36;
        moveGain.connect(master);
        for (const [name,encoded] of Object.entries(moveRecordings)) {
          decode(encoded).then(b => samples.set(name,b)).catch(() => {});
        }
        for (const label of ['3','2','1','GO!','GAME!']) {
          calls.set(label,decode(recordings[label]).catch(() => null));
        }
        decode(recordings.music).then(buffer => { musicBuffer = buffer; playMusic(); }).catch(() => {});
      }
      if (context.state !== 'running') return context.resume().catch(() => {});
    }

    function announce(label) {
      if (!context || !enabled || paused) return;
      const clip = calls.get(String(label).toUpperCase());
      if (!clip) return;
      silenceVoice();
      const id = announcement;
      clip.then(buffer => {
        if (!buffer || id !== announcement || !enabled || paused) return;
        const voice = context.createBufferSource();
        voice.buffer = buffer;
        voice.connect(voiceGain);
        voiceNode = voice;
        voice.onended = () => {
          voice.disconnect();
          if (voiceNode === voice) voiceNode = null;
        };
        voice.start();
      });
    }

    return {
      unlock, announce, updateMoves,
      setEnabled(on) {
        enabled = on;
        if (master) master.gain.value = on ? 1 : 0;
        if (!on) { silenceVoice(); clearMoves(); }
      },
      start() {
        stopMusic(false); silenceVoice(); clearMoves();
        active = true; paused = false; offset = 0;
        playMusic();
      },
      pause() {
        if (!active || paused) return;
        paused = true;
        stopMusic(true); silenceVoice(); clearMoves();
      },
      resume() {
        if (!active || !paused) return;
        paused = false;
        playMusic();
      },
      stop() {
        active = false; paused = false; offset = 0;
        stopMusic(false); silenceVoice(); clearMoves();
      }
    };
  }

  // Voice and special SE: 101soundboards.com/boards/1618110 (Purin), 1618116 (Kirby).
  // General hits, guard, grass and wood: 101soundboards.com/boards/1618210.
  // Rest collision: myinstants.com/en/instant/ssbu-home-run-bat-22024/
  const moveRecordings = {
    "se_kirby_final01": "",
    "se_kirby_final02": "",
    "se_kirby_final03": "",
    "se_kirby_final04": "",
    "se_kirby_final05_l": "",
    "se_kirby_final06": "",
    "se_kirby_final08": "",
    "se_kirby_final09": "",
    "se_purin_final01": "",
    "se_purin_final02": "",
    "vc_kirby_010": "",
    "vc_kirby_final01": "",
    "vc_kirby_final02": "",
    "vc_purin_007": "",
    "se_kirby_attack100": "",
    "se_kirby_swing_m": "",
    "se_kirby_swing_s": "",
    "se_purin_swing_m": "",
    "se_purin_swing_s": "",
    "vc_kirby_attack02": "",

    "vc_kirby_appeal01": "",
    "vc_kirby_copy_purin_01": "",
    "cutup_l":"",
    "fire_l":"",
    "fire_m":"",
    "fire_s":"",
    "grass":"",
    "guard":"",
    "guardOff":"",
    "kick_l":"",
    "kick_m":"",
    "launch":"",
    "ledge":"",
    "parry":"",
    "punch_l":"",
    "punch_s":"",
    "shieldBreak":"",
    "shieldHit":"",
    "smashCharge":"",
    "throw":"",
    "wood":"",
    "rest_ping": "",
    "se_kirby_special_h01": "",
    "se_kirby_special_h02": "",
    "se_kirby_special_n01": "",
    "se_kirby_special_n07": "",
    "se_purin_sleep": "",
    "vc_kirby_002": "",
    "vc_kirby_006": "",
    "vc_kirby_008": "",
    "vc_purin_001": "",
    "vc_purin_003": "",
    "vc_purin_004": "",
  };

  const recordings = {
    "3": "",
    "2": "",
    "1": "",
    "GO!": "",
    "GAME!": "",
    "music": "",
  };
  globalThis.BattleAudio = {create};
})();
